import java.io.*;
import java.util.*;

class FastScanner {
    private InputStream in = System.in;
    private byte[] buf = new byte[1 << 16];
    private int cur = 0, len = 0;

    private int read() throws IOException {
        if (cur >= len) {
            len = in.read(buf);
            cur = 0;
            if (len <= 0) return -1;
        }
        return buf[cur++] & 0xff;
    }

    public int nextInt() throws IOException {
        int c = read();
        while (c <= ' ') c = read();
        int sgn = 1;
        if (c == '-') { sgn = -1; c = read(); }
        int res = 0;
        while (c > ' ') {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res = res * 10 + (c - '0');
            c = read();
        }
        return res * sgn;
    }

    public String next() throws IOException {
        StringBuilder sb = new StringBuilder();
        int c = read();
        while (c <= ' ') c = read();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        String Str = fs.next();
        int count = 0, par = 0, wordInPar = 0, max_length = 0;
        for (int i = 0, n = Str.length(); i < n; i++) {
            char c = Str.charAt(i);
            if (c == '_') {
                if (par == 0) {
                    max_length = Math.max(max_length, count);
                } else if (count > 0) {
                    wordInPar++;
                }
                count = 0;
            } else if (c == '(') {
                par = 1;
                max_length = Math.max(max_length, count);
                count = 0;
            } else if (c == ')') {
                par = 0;
                if (count > 0) {
                    wordInPar++;
                }
                count = 0;
            } else {
                count++;
            }
            if (par == 0) {
                max_length = Math.max(max_length, count);
            }
        }
        System.out.println(max_length + " " + wordInPar);
    }
}
